# Bullseye layouts.
#
# The CSEA (mouse cell types) and TSEA (tissues) bullseyes of the original
# tools place the hexagons on a hand-drawn tree: a dendrogram of the expression
# data whose nodes the lab positioned by hand in igraph's tkplot. Those node
# positions, the edges, the hexagon positions (for CSEA ten of them were nudged
# after the tree was laid out) and the CSEA label texts come from the lab's
# original layout files and are in layout_tables.R, generated by
# dev/layouts_from_originals.R in the pixel coordinates of the tools' output
# images. The adult-brain and developmental panels use a row and a region x
# period grid.
#
# Coordinates are pixels of the original images, origin top-left (y grows
# downwards); layout_nodes() flips y so that the plot draws them the right way up.

CSEA_FRAME <- c(width = 1500, height = 1125)
CSEA_R_MAX <- 87.5       # outer (pSI < 0.05) radius of the largest cell type, px
CSEA_TREE_WIDTH <- 5     # tree line width, px of the original image (5 of 1500)
CSEA_LABEL_CEX <- 1.12   # label scale: label widths measured in the original image / ours at cex 0.74

TSEA_FRAME <- c(width = 1000, height = 750)
TSEA_R_MAX <- 55
TSEA_TREE_WIDTH <- 4.5   # 4-5 px of 1000
TSEA_LABEL_CEX <- 1.65

# Tree edges as line segments in frame coordinates (y flipped to grow upwards).
tree_segments <- function(tree_nodes, edges, frame) {
  y <- frame[["height"]] - tree_nodes$y
  a <- match(edges$from, tree_nodes$node); b <- match(edges$to, tree_nodes$node)
  data.frame(x0 = tree_nodes$x[a], y0 = y[a], x1 = tree_nodes$x[b], y1 = y[b])
}

# Node positions, label text and hexagon scale for one panel.
#
# columns: the panel's column table (code, label, group, ...).
# n05:     named vector, number of genes with pSI < 0.05 per column (hexagon
#          sizes are proportional to sqrt(list size), so the largest list in
#          the panel gets radius r_max).
#
# Returns list(nodes = data.frame(code, x, y, label, sublabel), frame, k,
# segments, tree_width, label_cex, ...) where k converts sqrt(number of genes)
# to a radius in frame units, segments is a data frame of tree line segments
# (x0, y0, x1, y1) or NULL, and label_cex scales the node labels.
layout_nodes <- function(layout, columns, n05) {
  if (layout == "csea") {
    nodes <- CSEA_NODES
    nodes$y <- CSEA_FRAME[["height"]] - nodes$y
    nodes$sublabel <- columns$group[match(nodes$code, columns$code)]
    return(list(nodes = nodes, frame = CSEA_FRAME, k = CSEA_R_MAX / sqrt(max(n05[nodes$code])),
                segments = tree_segments(CSEA_TREE_NODES, CSEA_TREE_EDGES, CSEA_FRAME),
                tree_width = CSEA_TREE_WIDTH, label_above = TRUE, label_cex = CSEA_LABEL_CEX))
  }
  if (layout == "tsea") {
    nodes <- TSEA_TREE_NODES[TSEA_TREE_NODES$node %in% columns$code, ]
    nodes <- data.frame(code = nodes$node, x = nodes$x, y = TSEA_FRAME[["height"]] - nodes$y,
                        stringsAsFactors = FALSE)
    i <- match(nodes$code, columns$code)
    nodes$label <- columns$label[i]
    nodes$sublabel <- NA_character_
    return(list(nodes = nodes, frame = TSEA_FRAME, k = TSEA_R_MAX / sqrt(max(n05[nodes$code])),
                segments = tree_segments(TSEA_TREE_NODES, TSEA_TREE_EDGES, TSEA_FRAME),
                tree_width = TSEA_TREE_WIDTH, label_above = FALSE, outer_faint = TRUE,
                label_cex = TSEA_LABEL_CEX))
  }
  if (layout == "row") {
    n <- nrow(columns); sp <- 190
    nodes <- data.frame(code = columns$code, x = sp * (seq_len(n) - 0.5) + 180, y = 250,
                        label = columns$label, sublabel = columns$group, stringsAsFactors = FALSE)
    return(list(nodes = nodes, frame = c(width = sp * n + 360, height = 420),
                k = 92 / sqrt(max(n05)), segments = NULL, label_above = TRUE))
  }
  if (layout == "grid") {
    regions <- unique(columns$region)
    periods <- unique(columns$period[order(columns$period_order)])
    cs <- 167; rs <- 94
    col <- match(columns$region, regions); row <- match(columns$period, periods)
    nodes <- data.frame(code = columns$code, x = 250 + cs * (col - 1), y = 150 + rs * (row - 1),
                        label = NA_character_, sublabel = NA_character_, stringsAsFactors = FALSE)
    frame <- c(width = 250 + cs * (length(regions) - 1) + 150, height = 150 + rs * (length(periods) - 1) + 80)
    nodes$y <- frame[["height"]] - nodes$y
    headers <- data.frame(
      x = c(250 + cs * (seq_along(regions) - 1), rep(95, length(periods))),
      y = frame[["height"]] - c(rep(75, length(regions)), 150 + rs * (seq_along(periods) - 1)),
      text = c(regions, vapply(periods, function(s) paste(strwrap(s, 12), collapse = "\n"), "")),
      stringsAsFactors = FALSE)
    return(list(nodes = nodes, frame = frame, k = 56 / sqrt(max(n05)), segments = NULL,
                label_above = TRUE, headers = headers))
  }
  stop("unknown layout: ", layout)
}
